import struct

def keccak256(msg: bytes) -> bytes:
    state = [0] * 25
    RC = [
        0x0000000000000001, 0x000000000000808A, 0x800000000000808A, 0x8000000080008000,
        0x000000000000808B, 0x0000000080000001, 0x8000000080008081, 0x8000000000008009,
        0x000000000000008A, 0x0000000000000088, 0x0000000080008009, 0x000000008000000A,
        0x000000008000808B, 0x800000000000008B, 0x8000000000008089, 0x8000000000008003,
        0x8000000000008002, 0x8000000000000080, 0x000000000000800A, 0x800000008000000A,
        0x8000000080008081, 0x8000000000008080, 0x0000000080000001, 0x8000000080008008,
    ]
    rot = [[0]*5 for _ in range(5)]
    x, y = 1, 0
    for t in range(24):
        rot[x][y] = ((t + 1) * (t + 2) // 2) % 64
        x, y = y, (2 * x + 3 * y) % 5

    def keccak_f(st):
        for round_idx in range(24):
            C = [st[x] ^ st[x+5] ^ st[x+10] ^ st[x+15] ^ st[x+20] for x in range(5)]
            D = [C[(x+4)%5] ^ (((C[(x+1)%5] << 1) | (C[(x+1)%5] >> 63)) & 0xFFFFFFFFFFFFFFFF) for x in range(5)]
            for x_i in range(5):
                for y_i in range(5):
                    st[x_i + 5*y_i] ^= D[x_i]

            B = [0] * 25
            for x_i in range(5):
                for y_i in range(5):
                    shift = rot[x_i][y_i]
                    val = st[x_i + 5*y_i]
                    rot_val = ((val << shift) | (val >> (64 - shift))) & 0xFFFFFFFFFFFFFFFF if shift != 0 else val
                    nx, ny = y_i, (2*x_i + 3*y_i) % 5
                    B[nx + 5*ny] = rot_val

            for x_i in range(5):
                for y_i in range(5):
                    st[x_i + 5*y_i] = B[x_i + 5*y_i] ^ ((~B[(x_i+1)%5 + 5*y_i]) & B[(x_i+2)%5 + 5*y_i])

            st[0] ^= RC[round_idx]

    block_size = 136
    p_msg = bytearray(msg)
    p_msg.append(0x01)
    while len(p_msg) % block_size != 0:
        p_msg.append(0x00)
    p_msg[-1] |= 0x80

    for i in range(0, len(p_msg), block_size):
        block = p_msg[i:i+block_size]
        for j in range(block_size // 8):
            val = struct.unpack('<Q', block[j*8:(j+1)*8])[0]
            state[j] ^= val
        keccak_f(state)

    out = bytearray()
    for j in range(4):
        out.extend(struct.pack('<Q', state[j]))
    return bytes(out)

def selector_hash(sig: str) -> str:
    return keccak256(sig.encode('utf-8')).hex()[:8]
