class Token:
    def __init__(self, kind, val, line, col):
        self.kind = kind
        self.val = val
        self.line = line
        self.col = col

    def __repr__(self):
        return f"Token({self.kind}, {self.val!r}, {self.line}:{self.col})"

def tokenize(code):
    tokens = []
    i = 0
    n = len(code)
    line = 1
    col = 1

    while i < n:
        c = code[i]

        # Newlines
        if c == '\n':
            line += 1
            col = 1
            i += 1
            continue

        # Whitespace
        if c.isspace():
            col += 1
            i += 1
            continue

        # Comments
        if c == '/' and i + 1 < n:
            if code[i+1] == '/':
                # Line comment
                i += 2
                col += 2
                while i < n and code[i] != '\n':
                    i += 1
                    col += 1
                continue
            elif code[i+1] == '*':
                # Block comment
                i += 2
                col += 2
                while i + 1 < n and not (code[i] == '*' and code[i+1] == '/'):
                    if code[i] == '\n':
                        line += 1
                        col = 1
                    else:
                        col += 1
                    i += 1
                i += 2
                col += 2
                continue

        # Strings
        if c in ('"', "'"):
            quote = c
            start_col = col
            i += 1
            col += 1
            s_val = []
            while i < n and code[i] != quote:
                if code[i] == '\\' and i + 1 < n:
                    s_val.append(code[i:i+2])
                    i += 2
                    col += 2
                else:
                    if code[i] == '\n':
                        line += 1
                        col = 1
                    else:
                        col += 1
                    s_val.append(code[i])
                    i += 1
            i += 1 # skip closing quote
            col += 1
            tokens.append(Token('STRING', "".join(s_val), line, start_col))
            continue

        # Hex strings or Hex numbers or Identifiers / Keywords
        if c.isalpha() or c in ('_', '$'):
            start_col = col
            start_i = i
            while i < n and (code[i].isalnum() or code[i] in ('_', '$')):
                i += 1
                col += (i - start_i) # wait
            val = code[start_i:i]
            col = start_col + len(val)
            tokens.append(Token('IDENT', val, line, start_col))
            continue

        # Numbers
        if c.isdigit():
            start_col = col
            start_i = i
            if c == '0' and i + 1 < n and code[i+1] in ('x', 'X'):
                i += 2
                while i < n and code[i].isxdigit():
                    i += 1
            else:
                while i < n and (code[i].isdigit() or code[i] == '.'):
                    i += 1
            val = code[start_i:i]
            col = start_col + len(val)
            tokens.append(Token('NUMBER', val, line, start_col))
            continue

        # Multi-char symbols
        if i + 1 < n:
            two = code[i:i+2]
            if two in ('=>', '==', '!=', '<=', '>=', '&&', '||', '++', '--', '+=', '-=', '*=', '/='):
                tokens.append(Token('SYMBOL', two, line, col))
                i += 2
                col += 2
                continue

        # Single-char symbols
        tokens.append(Token('SYMBOL', c, line, col))
        i += 1
        col += 1

    return tokens

