class Parser:
    def __init__(self, tokens, file_path):
        self.tokens = tokens
        self.file_path = file_path
        self.pos = 0
        self.n = len(tokens)

    def peek(self, offset=0):
        p = self.pos + offset
        if p < self.n:
            return self.tokens[p]
