                imp = self.parse_import()
                if imp:
                    unit["imports"].append(imp)
            elif tok.val == "enum":
                enum_def = self.parse_enum()
                unit["enums"][enum_def["name"]] = enum_def
            elif tok.val == "struct":
                struct_def = self.parse_struct()
                unit["structs"][struct_def["name"]] = struct_def
            elif tok.val == "type":
                udvt_def = self.parse_udvt()
                unit["udvts"][udvt_def["name"]] = udvt_def
            elif tok.val == "error":
