        while self.pos < self.n:
            tok = self.peek()
            self.pos += 1
            if tok.val == end_symbol:
                break

    def parse_import(self):
        self.expect("import")
        # Handles import "file.sol"; import { A } from "file.sol"; import * as X from "file.sol";
        path = None
        while self.pos < self.n:
            tok = self.peek()
            if tok.kind == "STRING":
                path = tok.val
            elif tok.val == ";":
                self.pos += 1
                break
            else:
                self.pos += 1
