            while self.match("."):
                parts.append(self.expect("IDENT").val)
            base = {"kind": "user_or_elem", "name": ".".join(parts)}

        while self.peek().val == "[":
            self.pos += 1
            size = ""
            if self.peek().val != "]":
                size = self.peek().val
                self.pos += 1
            self.expect("]")
            base = {"kind": "array", "element": base, "size": size}

        return base

    def parse_parameter_list(self, closing_char=")", is_event=False):
        params = []
        if self.peek().val == closing_char:
            self.pos += 1
            return params

        while self.pos < self.n:
            param_type = self.parse_type()
            indexed = False
            data_loc = None
            name = ""

            while self.pos < self.n and self.peek().val not in (",", closing_char):
                val = self.peek().val
                if is_event and val == "indexed":
                    indexed = True
                    self.pos += 1
                elif val in ("memory", "calldata", "storage"):
                    data_loc = val
                    self.pos += 1
                elif self.peek().kind == "IDENT":
                    name = val
                    self.pos += 1
                else:
                    self.pos += 1

            p_obj = {
                "type_ast": param_type,
                "name": name,
            }
            if is_event:
                p_obj["indexed"] = indexed

            params.append(p_obj)

            if self.match(","):
                continue
            elif self.match(closing_char):
                break
            else:
                self.pos += 1

        return params

    def parse_variable_decl(self, ending=";"):
        var_type = self.parse_type()
        vis = None
        mutability = None
        name = None

        while self.pos < self.n and self.peek().val != ending:
            tok = self.peek()
            if tok.val in ("public", "internal", "private"):
                vis = tok.val
                self.pos += 1
            elif tok.val in ("constant", "immutable"):
                mutability = tok.val
                self.pos += 1
            elif tok.val in ("memory", "calldata", "storage"):
                self.pos += 1
            elif tok.val == "=":
                break
            elif tok.kind == "IDENT" and name is None:
                name = tok.val
                self.pos += 1
            else:
                self.pos += 1

        if self.peek().val == "=":
            self.skip_until(ending)
        elif self.peek().val == ending:
            self.pos += 1

        return {
            "type_ast": var_type,
            "name": name or "",
            "visibility": vis or "internal",
            "mutability": mutability
        }

    def parse_contract(self):
        kind_tok = self.peek()
        is_abstract = False
        if kind_tok.val == "abstract":
            is_abstract = True
            self.pos += 1
            kind_tok = self.peek()

        contract_kind = kind_tok.val
        self.pos += 1

        name = self.expect("IDENT").val

        bases = []
        if self.match("is"):
            while self.pos < self.n and self.peek().val != "{":
                b_name = self.expect("IDENT").val
                bases.append(b_name)
                if self.peek().val == "(":
                    self.pos += 1
                    d = 1
                    while self.pos < self.n and d > 0:
                        if self.peek().val == "(": d += 1
                        elif self.peek().val == ")": d -= 1
                        self.pos += 1
                self.match(",")

        self.expect("{")

        contract = {
            "kind": contract_kind,
            "abstract": is_abstract,
            "name": name,
            "bases": bases,
            "enums": {},
            "structs": {},
            "udvts": {},
            "errors": [],
            "events": [],
            "state_variables": [],
            "constructor": None,
            "fallback": None,
            "receive": None,
            "functions": []
        }

        while self.pos < self.n and self.peek().val != "}":
            tok = self.peek()

            if tok.val == "enum":
                enum_def = self.parse_enum()
                contract["enums"][enum_def["name"]] = enum_def

            elif tok.val == "struct":
                struct_def = self.parse_struct()
                contract["structs"][struct_def["name"]] = struct_def

            elif tok.val == "type":
                udvt_def = self.parse_udvt()
                contract["udvts"][udvt_def["name"]] = udvt_def

            elif tok.val == "error":
                err_def = self.parse_error()
                contract["errors"].append(err_def)

            elif tok.val == "event":
                evt_def = self.parse_event()
                contract["events"].append(evt_def)

            elif tok.val == "constructor":
                ctor_def = self.parse_function_or_ctor()
                contract["constructor"] = ctor_def

            elif tok.val == "fallback":
                fb_def = self.parse_function_or_ctor()
                contract["fallback"] = fb_def

            elif tok.val == "receive":
                rec_def = self.parse_function_or_ctor()
                contract["receive"] = rec_def

            elif tok.val == "function":
                func_def = self.parse_function_or_ctor()
                contract["functions"].append(func_def)

            elif tok.val in ("using", "modifier"):
                self.skip_body_or_semi()

            else:
                var_def = self.parse_variable_decl(ending=";")
                if var_def:
                    contract["state_variables"].append(var_def)

        self.expect("}")
        return contract

    def skip_body_or_semi(self):
        while self.pos < self.n:
            tok = self.peek()
            if tok.val == ";":
                self.pos += 1
                break
            elif tok.val == "{":
                self.pos += 1
                d = 1
                while self.pos < self.n and d > 0:
                    if self.peek().val == "{": d += 1
                    elif self.peek().val == "}": d -= 1
                    self.pos += 1
                break
            else:
                self.pos += 1

    def parse_function_or_ctor(self):
        tok = self.expect(self.peek().val)
        kind = tok.val

        name = None
        if kind == "function":
            if self.peek().kind == "IDENT":
                name = self.peek().val
                self.pos += 1

        params = []
        if self.peek().val == "(":
            self.expect("(")
            params = self.parse_parameter_list(")")

        vis = None
        mutability = None
        returns = []

        while self.pos < self.n and self.peek().val not in ("{", ";"):
            val = self.peek().val
            if val in ("public", "external", "internal", "private"):
                vis = val
                self.pos += 1
            elif val in ("pure", "view", "payable"):
                mutability = val
                self.pos += 1
            elif val == "returns":
                self.pos += 1
                self.expect("(")
                returns = self.parse_parameter_list(")")
            else:
                self.pos += 1

        self.skip_body_or_semi()

        if kind == "constructor":
            stateMutability = mutability or "nonpayable"
            return {"kind": "constructor", "inputs": params, "stateMutability": stateMutability}

        elif kind == "fallback":
            stateMutability = mutability or "nonpayable"
            return {"kind": "fallback", "stateMutability": stateMutability}

        elif kind == "receive":
            return {"kind": "receive", "stateMutability": "payable"}

        else:
            stateMutability = mutability or "nonpayable"
            visibility = vis or "public"
            return {
                "kind": "function",
                "name": name,
                "inputs": params,
                "outputs": returns,
                "visibility": visibility,
                "stateMutability": stateMutability
            }
EOF
"}
